import{Z as t,e as a,f as n,a0 as i}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"Connect and Test an Integration","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/connect-and-test-an-integration.md","filePath":"integrations/connect-and-test-an-integration.md","lastUpdated":null}'),s={name:"integrations/connect-and-test-an-integration.md"};function o(r,e,d,h,l,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="connect-and-test-an-integration" tabindex="-1">Connect and Test an Integration <a class="header-anchor" href="#connect-and-test-an-integration" aria-label="Permalink to &quot;Connect and Test an Integration&quot;">​</a></h1><p>An integration sends a form submission to another system. Connecting an account gives Formie credentials; mapping tells it which answers to send. A test submission confirms that the receiving system accepts those values.</p><p>This walkthrough uses a newsletter form and Beehiiv. You need a Beehiiv account with a publication, access to its API key, and permission to edit Formie integrations and forms. Follow <a href="/integrations/email-marketing/beehiiv">Beehiiv</a> to save the credentials and refresh the available publications before continuing.</p><h2 id="create-a-newsletter-form" tabindex="-1">Create a Newsletter Form <a class="header-anchor" href="#create-a-newsletter-form" aria-label="Permalink to &quot;Create a Newsletter Form&quot;">​</a></h2><p>Create a form named <strong>Newsletter Signup</strong>, with handle <code>newsletterSignup</code>. Add a required Email Address field with handle <code>emailAddress</code>, and an Agree field named <strong>Send Me the Newsletter</strong>. Save the form.</p><p>The Agree field lets the visitor choose whether the integration should run. It is separate from any confirmation email or subscription-state rules in your mailing platform.</p><h2 id="map-the-email-address" tabindex="-1">Map the Email Address <a class="header-anchor" href="#map-the-email-address" aria-label="Permalink to &quot;Map the Email Address&quot;">​</a></h2><p>Open the form’s <strong>Integrations</strong> tab and select your Beehiiv integration. Enable it and choose the publication that should receive sign-ups. In its mapping, connect the required <strong>Email</strong> destination to your form’s <strong>Email Address</strong> field using the variable picker. Do not type the field handle as plain text: a literal value would be sent unchanged for every submission.</p><p>Beehiiv also exposes <strong>Reactivate Existing</strong> and <strong>Send Welcome Email</strong>. Choose those values deliberately. Reactivating a contact and sending a welcome email are separate decisions from copying the email address. Leave additional custom fields unmapped unless your workflow needs them or the destination requires them.</p><p>Configure the integration’s conditions so it runs only when <strong>Send Me the Newsletter</strong> is checked. Save the form.</p><h2 id="submit-through-the-site" tabindex="-1">Submit Through the Site <a class="header-anchor" href="#submit-through-the-site" aria-label="Permalink to &quot;Submit Through the Site&quot;">​</a></h2><p>Create <code>templates/newsletter.twig</code> in the Craft project:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;newsletterSignup&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) }}</span></span></code></pre></div><p>Open <code>/newsletter</code>, enter a test mailbox you control, select the newsletter option and submit. Check <strong>Formie → Submissions</strong> for the completed record, then open the chosen Beehiiv publication and find that email address. Confirm the address, custom fields you mapped and subscription state. If your selected settings send a welcome email, inspect that mailbox too.</p><p>Submit again with another test address and leave the newsletter option unchecked. The form should still follow its own validation and completion rules, but this integration should not add that address to the publication. This second test checks the condition rather than only the connection.</p><h2 id="diagnose-missing-or-incorrect-data" tabindex="-1">Diagnose Missing or Incorrect Data <a class="header-anchor" href="#diagnose-missing-or-incorrect-data" aria-label="Permalink to &quot;Diagnose Missing or Incorrect Data&quot;">​</a></h2><p>If Formie saved the enquiry but the subscriber is missing, first check the integration condition and selected publication. Then check the Craft queue for a pending or failed job. Queued work needs a worker that runs without someone visiting the control panel; see <a href="/get-started/troubleshooting">Troubleshooting</a>.</p><p>A rejected payload usually needs a mapping correction or a destination-specific required value. Compare the saved answers with the mapped destination fields. Avoid repeating a send until you know whether the provider already accepted the first request, especially for messages, payments or workflows that create duplicate records.</p><p>After fixing the cause, use <a href="/guides/integrations/re-run-failed-integrations-from-the-control-panel">Re-run Failed Integrations</a> where appropriate, then check the destination again. Remove test contacts and records when you finish.</p><h2 id="apply-the-same-checks-to-other-providers" tabindex="-1">Apply the Same Checks to Other Providers <a class="header-anchor" href="#apply-the-same-checks-to-other-providers" aria-label="Permalink to &quot;Apply the Same Checks to Other Providers&quot;">​</a></h2><p>A CRM may need a contact, organisation or deal; an automation may need a webhook payload; a messaging integration needs a recipient or channel. Use the selected provider’s page for its actual settings. In each case, verify credentials, map the required values, submit through the real form and inspect the resulting record or message. A successful <strong>Refresh</strong> or <strong>Connect</strong> action covers only the account connection.</p>',21)])])}const g=t(s,[["render",o]]);export{u as __pageData,g as default};
